package terraform

import (
	"encoding/json"
	"errors"
	"os"

	"github.com/cloudposse/atmos/pkg/schema"
)

// snapshotPublicFiles preserves retained generated bytes after before-hooks have run.
// Missing files retain their preparation semantics; sensitive bytes never enter this record.
func snapshotPublicFiles(workdir string, files []schema.ComponentConfigurationFile) (string, error) {
	root, err := os.OpenRoot(workdir)
	if err != nil {
		return "", planIOError(err)
	}
	defer root.Close()
	contents := make(map[string][]byte)
	for _, file := range files {
		if file.Sensitive || file.IfExists == "remove" || file.IfExists == "remove_terragrunt" {
			continue
		}
		data, err := root.ReadFile(file.Path)
		if errors.Is(err, os.ErrNotExist) {
			continue
		}
		if err != nil {
			return "", planIOError(err)
		}
		contents[file.Path] = data
	}
	data, err := json.Marshal(contents)
	return string(data), err
}
